<script setup lang="ts">
import { computed,reactive,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { fetchPersonnelHistory } from '../../api/account'
import { useBusinessRead } from '../../composables/useBusinessRead'
import PersonnelCard from '../../components/account/PersonnelCard.vue'
import {personnelListReturn} from './personnel-navigation'
const route=useRoute(),router=useRouter(),form=reactive({keyword:'',status:''}),page=computed(()=>Math.max(1,Number(route.query.page)||1)),category=computed(()=>typeof route.query.category==='string'?route.query.category:undefined)
const listReturn=computed(()=>personnelListReturn(route.query.listReturn))
const {data,loading,message,stale,load,clear}=useBusinessRead(()=>fetchPersonnelHistory(String(route.params.id),{category:category.value,page:page.value,pageSize:20,keyword:typeof route.query.keyword==='string'?route.query.keyword:undefined,requestStatus:category.value==='REQUESTS'?typeof route.query.status==='string'?route.query.status:undefined:undefined,workOrderStatus:category.value!=='REQUESTS'?typeof route.query.status==='string'?route.query.status:undefined:undefined}),undefined,{target:()=>route.fullPath})
watch(()=>route.fullPath,()=>{form.keyword=typeof route.query.keyword==='string'?route.query.keyword:'';form.status=typeof route.query.status==='string'?route.query.status:'';clear();void load()},{immediate:true})
const selected=computed(()=>category.value??data.value?.availableCategories[0]??'')
const categoryNames:Record<string,string>={REQUESTS:'全部申请',RELATED_ORDERS:'关联工单',CURRENT_TASKS:'当前任务',HISTORICAL_ORDERS:'历史关联工单'}
const relations:Record<string,string>={SUBMITTER:'报修人',CURRENT_ASSIGNEE:'当前分派',ACTUAL_REPAIRER:'实际承担维修',COMPLETED_BY_ME:'本人完成',REFUSED:'曾拒单',REPLACED:'接单前被改派'}
function search(next=1){void router.push({path:route.path,query:{category:selected.value,status:form.status,keyword:form.keyword,page:String(next),listReturn:listReturn.value}})}
function turnPage(next:number){void router.push({path:route.path,query:{...route.query,page:String(next)}})}
function changeCategory(value:string){void router.push({path:route.path,query:{category:value,page:'1',listReturn:listReturn.value}})}
const time=(value:string)=>new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})
</script>
<template><div class="page-heading"><h1>人员详情 / 完整历史</h1><RouterLink :to="listReturn">返回人员列表</RouterLink><button class="secondary" :disabled="loading" @click="load">刷新</button></div><p v-if="message" class="notice" role="alert">{{message}}</p><p v-if="loading">正在读取人员历史…</p><template v-if="data"><PersonnelCard :person="data.person" :back="listReturn" :blocked="loading||stale" @changed="load"/><RouterLink v-if="data.person.allowedActions.includes('RESET_PASSWORD')&&!stale&&!loading" class="secondary link-button" :to="{path:`/admin/personnel/${data.person.id}/reset-password`,query:{detailReturn:route.fullPath}}">重置普通账号密码</RouterLink><section class="card"><h2>完整关联业务</h2><p>业务摘要与各分类总数不受列表入口及本页筛选影响。</p><div class="actions"><button v-for="key in data.availableCategories" :key="key" class="secondary" :aria-pressed="selected===key" @click="changeCategory(key)">{{categoryNames[key]}}（{{data.categoryTotals[key]}}）</button></div><p v-if="!data.availableCategories.length">管理员通过全局业务入口查看记录。</p><form v-else @submit.prevent="search()"><label>业务状态<select v-model="form.status"><option value="">全部状态</option><option v-for="(count,status) in data.statusCounts" :key="status" :value="status">{{status}}（{{count}}）</option></select></label><label>编号 / 设备名称<input v-model="form.keyword" maxlength="100"></label><div class="actions"><button class="primary" type="submit">查询业务</button><button class="secondary" type="button" @click="changeCategory(selected)">重置业务查询</button></div></form><p>分类总数 {{data.categoryTotals[selected]??0}} / 符合条件 {{data.records.total}} 条</p><p v-if="!data.records.records.length">暂无关联业务或当前筛选无结果。</p><article v-for="item in data.records.records" :key="item.resourceType+item.id" class="history-item"><h3>{{item.businessNo}} · {{item.equipmentName}}</h3><p>{{item.status}} · {{time(item.createdAt)}}</p><p>关联关系：{{item.relations.map(r=>relations[r]).join('、')}}</p><RouterLink v-if="item.canViewDetail" :to="{path:item.resourceType==='REPAIR_REQUEST'?`/admin/requests/${item.id}`:`/work-orders/${item.id}`,query:{returnTo:route.fullPath}}">查看业务详情</RouterLink></article><div class="actions"><button class="secondary" :disabled="page<=1||loading" @click="turnPage(page-1)">上一页</button><span>第 {{page}} 页</span><button class="secondary" :disabled="page*data.records.pageSize>=data.records.total||loading" @click="turnPage(page+1)">下一页</button></div></section></template></template>
<style scoped>.card{margin:16px 0}.history-item{padding:12px 0;border-bottom:1px solid #ddd;overflow-wrap:anywhere}.actions{flex-wrap:wrap}</style>


